-- gulhi
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, South Male Atoll"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 600 residents"},{"label":"Size","value":"0.5 km long, 0.3 km wide"},{"label":"Distance from Male","value":"27 km"},{"label":"Transfer Options","value":"Public ferry, speedboat"},{"label":"Known For","value":"Beautiful beaches, great snorkeling, authentic culture"},{"label":"Best For","value":"Couples, solo travelers, budget travelers"}],"island_overview":["Located in the Kaafu Atoll approximately 27 kilometers south of Male, Gulhi Island offers visitors an authentic Maldivian experience with pristine natural beauty and warm local hospitality. This charming island maintains its traditional character while providing excellent facilities for tourists seeking an affordable yet memorable stay in the Maldives.","What makes Gulhi special is its perfect combination of small-island charm and excellent tourism infrastructure. The island features beautiful beaches with powdery white sand and crystal-clear turquoise waters. The surrounding coral reefs are healthy and teeming with marine life, offering great snorkeling and diving opportunities right from the shore.","Visitors to Gulhi are drawn by its intimate atmosphere, excellent marine life, authentic cultural experiences, and budget-friendly accommodations. The island''s strategic location provides easy access to Male while offering a peaceful retreat from the busier capital city."],"island_sections":[{"heading":"Location & Map","paragraphs":["Gulhi Island is situated in the southern part of Kaafu Atoll (South Male Atoll), approximately 27 kilometers from Male. This location provides excellent access to both the capital and pristine coral reefs while maintaining the peaceful atmosphere of a traditional Maldivian island.","The island''s position offers protection from strong currents while still providing access to excellent snorkeling and diving sites. The surrounding lagoon features crystal-clear waters with good visibility, making it perfect for underwater exploration and water sports activities."]},{"heading":"Gulhi: Beautiful Beaches & Natural Paradise","paragraphs":["Gulhi Island is renowned for its natural beauty, featuring pristine beaches and healthy coral reefs. The island offers visitors an unspoiled tropical paradise with crystal-clear waters and abundant marine life."]},{"heading":"Beautiful White Sand Beaches","paragraphs":["Gulhi boasts stunning white sand beaches with crystal-clear turquoise waters, offering the perfect setting for relaxation, swimming, and beach activities in a peaceful, intimate environment."]},{"heading":"Great Snorkeling","paragraphs":["The island''s house reef is easily accessible from shore and features vibrant coral formations with diverse marine life, making it perfect for snorkeling enthusiasts of all skill levels."]},{"heading":"Rich Marine Biodiversity","paragraphs":["The waters around Gulhi are home to abundant marine life including colorful reef fish, sea turtles, rays, and occasional reef sharks, providing excellent underwater experiences."]},{"heading":"Authentic Island Life","paragraphs":["Experience genuine Maldivian culture and hospitality in a traditional island setting, with opportunities to interact with friendly locals and learn about island traditions."]},{"heading":"Beach Paradise","paragraphs":["Gulhi''s beaches offer exceptional natural beauty:"]},{"heading":"Marine Environment","paragraphs":["The island''s marine ecosystem features:"]},{"heading":"Activities & Experiences","paragraphs":["Gulhi offers a variety of activities focused on marine adventures, cultural experiences, and natural exploration. The island''s pristine environment and friendly community provide excellent opportunities for both relaxation and adventure."]},{"heading":"Snorkeling","paragraphs":["Explore the vibrant house reef directly from shore or join boat excursions to nearby coral gardens and marine sanctuaries."]},{"heading":"Scuba Diving","paragraphs":["Discover underwater wonders at nearby dive sites with professional dive operators offering courses and guided dives."]},{"heading":"Sandbank Visits","paragraphs":["Experience pristine uninhabited sandbanks for picnics, swimming, and the ultimate desert island adventure."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for traditional night fishing experiences using hand lines under the starlit sky."]},{"heading":"Island Hopping","paragraphs":["Visit neighboring islands in Kaafu Atoll to experience different communities and explore diverse environments."]},{"heading":"Cultural Experiences","paragraphs":["Engage with local community life, learn traditional crafts, and experience authentic Maldivian hospitality."]},{"heading":"People & Community Life","paragraphs":["Gulhi is home to a close-knit community of approximately 600 residents who have embraced sustainable tourism while preserving their traditional way of life. The island''s population is known for their exceptional hospitality, strong community bonds, and commitment to maintaining their cultural heritage."]},{"heading":"Daily Life","paragraphs":["Life on Gulhi follows traditional Maldivian rhythms, beginning with morning prayers and continuing with fishing, tourism-related work, and community activities. The island maintains a peaceful atmosphere where traditional values coexist harmoniously with modern tourism development. Fishing remains an important livelihood alongside tourism services."]},{"heading":"Culture & Traditions","paragraphs":["Gulhi preserves authentic Maldivian cultural traditions including traditional music, dance, and crafts. The community celebrates Islamic festivals with enthusiasm and maintains traditional practices such as boat building, fishing techniques, and local cuisine preparation. Visitors can often observe or participate in cultural activities."]},{"heading":"Community Tourism","paragraphs":["The island has developed a sustainable approach to tourism that benefits the entire community. Many residents are involved in tourism services, from guesthouse operations to tour guiding, creating economic opportunities while maintaining the island''s authentic character and environmental integrity."]}],"island_faqs":[{"question":"How do I get to Gulhi Island?","answer":"Gulhi Island can be reached by public ferry or speedboat from Male. Most guesthouses can arrange speedboat transfers for guests."},{"question":"What is the best time to visit Gulhi?","answer":"The best time to visit Gulhi is during the dry season from December to April when you''ll experience sunny skies, calm seas, and minimal rainfall. This period offers the best conditions for beach activities, snorkeling, and diving. However, Gulhi can be visited year-round, with the wet season (May to November) offering lower prices and fewer crowds, though with occasional rain showers and rougher seas."},{"question":"What accommodation options are available on Gulhi?","answer":"Gulhi offers various budget-friendly and mid-range accommodations including family-run guesthouses, boutique hotels, and beachfront properties. Most accommodations offer air conditioning, private bathrooms, meal packages, and can arrange tours and transfers. Many properties have designated areas where Western-style swimwear is permitted."},{"question":"What activities can I do on Gulhi Island?","answer":"Gulhi offers excellent snorkeling directly from the beach with vibrant house reefs and diverse marine life. Other popular activities include scuba diving at nearby sites, sandbank excursions, traditional night fishing, island hopping tours, cultural experiences with the local community, and simply relaxing on pristine beaches. The island is perfect for those seeking authentic Maldivian experiences combined with natural beauty."}],"island_nearby_slugs":["himmafushi","huraa","dhiffushi","maafushi","guraidhoo","hulhumale","male","kaashidhoo","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'gulhi';


-- guraidhoo-thaa
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Thaa Atoll, Central Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,800 residents"},{"label":"Size","value":"1.6 km long, 1.0 km wide"},{"label":"Distance from Male","value":"205 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Splendid culture, beautiful beaches, excellent snorkeling"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, snorkelers, adventure seekers"}],"island_overview":["Guraidhoo Island is a splendid local island in Thaa Atoll that offers visitors a vibrant glimpse into traditional Maldivian life. This dynamic island combines natural beauty with an energetic atmosphere, providing an ideal destination for travelers seeking exciting cultural experiences and beautiful tropical surroundings.","Known for its gorgeous beaches, splendid coral reefs, and excellent marine biodiversity, Guraidhoo provides wonderful opportunities for snorkeling, swimming, and underwater exploration. The island''s vibrant community embraces visitors with traditional Maldivian warmth and shares their dynamic way of life with splendid hospitality.","What makes Guraidhoo special is its splendid natural environment and vibrant island setting. Visitors can enjoy beautiful beaches, explore rich marine ecosystems, and experience dynamic island culture while staying in comfortable accommodations that showcase the splendid Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Guraidhoo Island is beautifully located in the central part of Thaa Atoll, approximately 205 kilometers from Male. This location provides a splendid and vibrant experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to beautiful coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Thaa Atoll in its most splendid form."]},{"heading":"Guraidhoo: Splendid Paradise & Marine Vibrancy","paragraphs":["Guraidhoo Island is blessed with exceptional natural beauty, featuring beautiful white sand beaches, crystal-clear turquoise waters, and one of the most splendid marine environments in Thaa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a vibrant, dynamic setting."]},{"heading":"Beautiful White Sand Beaches","paragraphs":["Guraidhoo features splendid white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and dynamic beach activities."]},{"heading":"Splendid House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers vibrant snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Vibrant Island Community","paragraphs":["Experience the dynamic spirit of traditional island life with friendly locals and splendid Maldivian culture in a vibrant community setting."]},{"heading":"Dynamic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and beautiful islands around Guraidhoo for splendid tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Guraidhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Guraidhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Guraidhoo offers a perfect blend of marine adventures, cultural experiences, and splendid activities. The island''s vibrant environment and dynamic atmosphere provide ideal conditions for various activities in a beautiful, energetic setting."]},{"heading":"Splendid House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in splendid waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby beautiful dive sites with professional dive operators offering guided dives and certification courses in splendid marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, beautiful sandbanks, and discover the natural beauty of Thaa Atoll with vibrant exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in splendid community settings."]},{"heading":"Dynamic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience splendid Maldivian island life with vibrant cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy beautiful sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in splendid waters."]},{"heading":"Community Life & Culture","paragraphs":["Guraidhoo is home to approximately 1,800 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and splendid cultural traditions that create a vibrant atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Guraidhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains a splendid atmosphere where visitors can experience vibrant Maldivian culture and customs in their most dynamic, energetic setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this splendid island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Guraidhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and splendid cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Guraidhoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Thaa Atoll."},{"question":"What is the best time to visit Guraidhoo?","answer":"The best time to visit Guraidhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more splendid local atmosphere."},{"question":"What accommodation options are available on Guraidhoo?","answer":"Guraidhoo offers various accommodations including splendid guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a vibrant setting."},{"question":"What makes Guraidhoo''s vibrancy special?","answer":"Guraidhoo is known for its splendid and vibrant natural environment. The island maintains traditional Maldivian cultural practices while offering a dynamic atmosphere perfect for energetic exploration. Visitors can experience exciting cultural exchanges and participate in splendid community activities."}],"island_nearby_slugs":["guraidhoo","gaadhiffushi","dhiyamigili","burunee","vilufushi","veymandoo","vandhoo","thimarafushi","omadhoo","madifushi","kinbidhoo","kandoodhoo","hirilandhoo"]}'::jsonb
where node_type = 'location' and slug = 'guraidhoo-thaa';


-- guraidhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, South Male Atoll"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,200 residents"},{"label":"Size","value":"1.0 km long, 0.5 km wide"},{"label":"Distance from Male","value":"32 km"},{"label":"Transfer Options","value":"Public ferry, speedboat"},{"label":"Known For","value":"World-class diving, Guraidhoo Corner, marine life"},{"label":"Best For","value":"Diving enthusiasts, marine life lovers, cultural experiences"}],"island_overview":["Located in the southern part of Kaafu Atoll approximately 32 kilometers from Male, Guraidhoo Island stands out as one of the premier diving destinations in the Maldives. This charming local island combines world-class underwater experiences with authentic Maldivian culture, offering visitors an exceptional blend of adventure and cultural immersion.","What makes Guraidhoo truly special is its proximity to some of the most renowned dive sites in the Maldives, including the famous Guraidhoo Corner and nearby thilas (underwater pinnacles) that attract diverse marine life. The island''s strategic location at the southern edge of North Male Atoll provides access to both protected lagoon areas and exciting drift dive sites.","Visitors to Guraidhoo are drawn by its exceptional diving and snorkeling opportunities, beautiful beaches, vibrant local culture, and budget-friendly accommodations. The island has developed a strong reputation among diving enthusiasts while maintaining its authentic character and warm community atmosphere."],"island_sections":[{"heading":"Location & Map","paragraphs":["Guraidhoo Island is strategically positioned in the southern part of Kaafu Atoll (South Male Atoll), approximately 32 kilometers from Male. This location provides exceptional access to some of the Maldives'' most celebrated dive sites while maintaining the peaceful atmosphere of a traditional fishing island.","The island''s position at the atoll''s edge exposes it to nutrient-rich currents that support abundant marine life, making it a magnet for divers and snorkelers. The surrounding waters feature dramatic drop-offs, vibrant coral formations, and regular encounters with large pelagic species."]},{"heading":"Guraidhoo: World-Class Diving Paradise","paragraphs":["Guraidhoo Island is internationally recognized as one of the premier diving destinations in the Maldives, offering access to legendary dive sites, abundant marine life, and underwater experiences that attract divers from around the world."]},{"heading":"World-Class Dive Sites","paragraphs":["Access to famous dive sites including Guraidhoo Corner, nearby thilas, and dramatic drop-offs that offer encounters with large pelagic species and vibrant coral ecosystems."]},{"heading":"Abundant Marine Life","paragraphs":["Regular encounters with grey reef sharks, eagle rays, turtles, and schools of tropical fish, with seasonal opportunities to see whale sharks and manta rays."]},{"heading":"Excellent Snorkeling","paragraphs":["Beautiful house reef accessible from shore, plus boat excursions to pristine coral gardens and marine protected areas with crystal-clear visibility."]},{"heading":"Professional Dive Centers","paragraphs":["Multiple PADI dive centers offering courses from beginner to advanced levels, equipment rental, and guided dives to the best sites around the atoll."]},{"heading":"Famous Dive Sites","paragraphs":["Guraidhoo provides access to legendary dive sites:"]},{"heading":"Marine Encounters","paragraphs":["The waters around Guraidhoo offer incredible biodiversity:"]},{"heading":"Activities & Experiences","paragraphs":["While diving is the main attraction, Guraidhoo offers a variety of activities both underwater and on the surface, providing comprehensive marine experiences and cultural interactions for visitors of all interests."]},{"heading":"Scuba Diving","paragraphs":["Explore world-famous dive sites including Guraidhoo Corner with professional guides and encounter diverse marine life in pristine conditions."]},{"heading":"Snorkeling Adventures","paragraphs":["Discover vibrant house reefs from shore or join boat excursions to pristine coral gardens and marine sanctuaries."]},{"heading":"Whale Shark Encounters","paragraphs":["Seasonal opportunities to swim with gentle whale sharks at nearby aggregation sites during the southwest monsoon."]},{"heading":"Traditional Fishing","paragraphs":["Experience traditional Maldivian night fishing with local fishermen using hand lines under the starlit sky."]},{"heading":"Sandbank Visits","paragraphs":["Explore pristine uninhabited sandbanks for picnics, swimming, and the ultimate desert island experience."]},{"heading":"Cultural Immersion","paragraphs":["Engage with the local fishing community, learn traditional crafts, and experience authentic Maldivian island life."]},{"heading":"People & Community Life","paragraphs":["Guraidhoo is home to a vibrant community of approximately 1,200 residents who have successfully balanced traditional fishing livelihoods with sustainable dive tourism. The island''s population is known for their maritime expertise, warm hospitality, and deep connection to the ocean environment."]},{"heading":"Maritime Heritage","paragraphs":["As a traditional fishing island, Guraidhoo has a rich maritime heritage that extends back generations. Many residents are skilled fishermen and boat builders, with extensive knowledge of local waters, currents, and marine life. This expertise has naturally evolved to support the diving industry, with many locals becoming dive guides and boat operators."]},{"heading":"Diving Community","paragraphs":["The island has developed a strong diving community where traditional maritime skills complement modern dive tourism. Local dive guides possess intimate knowledge of dive sites, marine behavior, and safety protocols, making them invaluable partners for visiting divers seeking authentic underwater experiences."]},{"heading":"Cultural Preservation","paragraphs":["Despite the growth of dive tourism, Guraidhoo maintains its cultural traditions including traditional music, dance, and Islamic practices. The community celebrates religious festivals with enthusiasm and preserves traditional crafts, fishing techniques, and boat building skills that have been passed down through generations."]}],"island_faqs":[{"question":"What makes Guraidhoo special for diving?","answer":"Guraidhoo is renowned for its access to world-class dive sites, particularly the famous Guraidhoo Corner which offers regular encounters with grey reef sharks, eagle rays, and large schools of fish. The island''s location at the southern edge of North Male Atoll provides access to both protected lagoon sites and exciting drift dives with strong currents that attract diverse marine life. Multiple professional dive centers offer courses and guided dives to suit all experience levels."},{"question":"When is the best time for diving at Guraidhoo?","answer":"Diving at Guraidhoo is excellent year-round, but the best conditions are typically during the dry season from December to April when seas are calmer and visibility is at its peak (often exceeding 30 meters). However, the wet season (May to November) offers unique opportunities including whale shark encounters and manta ray sightings. Each season has its advantages: dry season for optimal conditions and wet season for larger pelagic species."},{"question":"How do I get to Guraidhoo Island?","answer":"Guraidhoo can be reached by public ferry or speedboat from Male. Many dive operators and guesthouses can arrange transfers that include dive equipment transport."},{"question":"What diving certifications and courses are available?","answer":"Guraidhoo has several PADI dive centers offering courses from beginner (Discover Scuba Diving, Open Water) to advanced levels (Advanced Open Water, Rescue Diver, Divemaster). Specialty courses like Nitrox, Deep Diving, and Underwater Photography are also available. The island''s diverse dive sites provide excellent training environments, from shallow lagoons for beginners to challenging drift dives for advanced divers. Equipment rental and Nitrox fills are readily available."}],"island_nearby_slugs":["himmafushi","huraa","dhiffushi","maafushi","gulhi","hulhumale","male","kaashidhoo","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'guraidhoo';


-- hangnaameedhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"What is the best time to visit Hangnaameedhoo?","answer":"The best time to visit Hangnaameedhoo depends on your interests. For the best weather conditions, visit during the dry season from December to April when skies are clear and seas are calm. This is ideal for beach activities and snorkeling. The wet season from May to November offers better chances to see manta rays and whale sharks, though there may be more rain. Water temperatures remain warm year-round (around 28-30C). For more information about Maldives weather patterns, see our Maldives Weather Guide."},{"question":"Do I need to bring my own snorkeling equipment?","answer":"The quality of rental equipment varies, so serious snorkelers might prefer to bring their own well-fitting mask. If you''re planning to do a lot of snorkeling, consider bringing reef-safe sunscreen to protect the coral. For diving, equipment is available for rent at the dive center, though many divers prefer to bring their own mask and snorkel at minimum."},{"question":"What makes Hangnaameedhoo different from other Maldivian islands?","answer":"Hangnaameedhoo stands out for its authentic local atmosphere and relatively undiscovered status compared to more touristy islands. Unlike resort islands, you''ll experience genuine Maldivian culture and hospitality. The island offers excellent value compared to resorts, with similar beautiful beaches and marine life at a fraction of the cost. Hangnaameedhoo''s house reef is particularly accessible, with vibrant coral just steps from shore. The island''s small size creates a peaceful, intimate atmosphere perfect for travelers looking to escape crowds. For comparisons with other islands, check our Maldives Islands Guide."},{"question":"Are there restaurants and shops on Hangnaameedhoo?","answer":"Hangnaameedhoo has several small local restaurants (called \"hotels\" in Maldivian terminology) serving authentic Maldivian cuisine, with fresh seafood as a staple. Most guesthouses offer meal plans with home-cooked local dishes. There are a few small shops selling basic necessities, snacks, and souvenirs, but selection is limited compared to Male or resort islands. It''s recommended to bring any specialty items you might need. The island has no alcohol available due to local customs. For more about Maldivian food, see our Maldives Culture article."},{"question":"What should I pack for a trip to Hangnaameedhoo?","answer":"Essential items for Hangnaameedhoo include: swimwear (for the designated bikini beach), cover-ups for village areas, reef-safe sunscreen, hat and sunglasses, lightweight clothing that covers shoulders and knees for village wear, sandals or water shoes, snorkeling gear (if you prefer your own), waterproof bag for boat trips, and a reusable water bottle. For electronics, bring waterproof cases, extra memory cards, and universal adapters (Maldives uses UK-style plugs). Mosquito repellent and after-bite cream are recommended. If visiting mosques, women should pack a light scarf. For more packing tips, see our Maldives Packing Guide."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'hangnaameedhoo';


-- hanimaadhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Hanimaadhoo Island?","answer":"Public ferry service operates weekly from Male (approximately 14 hours). Private speedboat transfers can be arranged but take significantly longer (about 8 hours from Male)."},{"question":"What is the best time to visit Hanimaadhoo Island?","answer":"The best time is during the northeast monsoon (December to April) with dry, sunny weather. The northern atolls can experience slightly different weather patterns than central/southern atolls. Water temperatures remain warm year-round (26-29C/79-84F)."},{"question":"What makes Hanimaadhoo different from other local islands?","answer":"Hanimaadhoo stands out for its northern location (with distinct marine life), airport access, and unique northern Maldivian cultural traditions. It offers more amenities than smaller northern islands while maintaining authentic character."},{"question":"Are there any dress code requirements on Hanimaadhoo?","answer":"As a local island, modest dress is required in public areas (shoulders and knees covered). Swimwear is only permitted at the designated \"bikini beach.\" These requirements don''t apply during water activities or at resort day visits."},{"question":"What marine life can I expect to see around Hanimaadhoo?","answer":"Hanimaadhoo''s waters feature northern coral species and fish populations that differ from central/southern atolls. Expect healthy coral formations, reef fish, and seasonal visitors. The northern location brings unique seasonal variations in marine life."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'hanimaadhoo';


-- henbandhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 600 residents"},{"label":"Size","value":"0.7 km long, 0.3 km wide"},{"label":"Distance from Male","value":"180 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat"},{"label":"Known For","value":"Pristine beaches, excellent fishing, peaceful atmosphere"},{"label":"Best For","value":"Culture seekers, snorkelers, budget travelers"}],"island_overview":["Located in the picturesque Noonu Atoll, Henbandhoo Island offers visitors a genuine taste of Maldivian island life away from the crowds. This charming local island combines natural beauty with authentic cultural experiences.","Henbandhoo stands out for its peaceful atmosphere, stunning beaches, and excellent snorkeling opportunities. The island maintains its traditional character while welcoming visitors with genuine Maldivian hospitality.","What makes Henbandhoo special is its unspoiled environment, rich marine life, and the opportunity to experience local culture. Visitors enjoy affordable accommodations, delicious Maldivian cuisine, and unforgettable island adventures."],"island_sections":[{"heading":"Location & Map","paragraphs":["Henbandhoo Island is located in the northern part of Noonu Atoll, approximately 180 kilometers from Male. This location offers a peaceful retreat while still being accessible from the capital.","The island''s position provides excellent access to some of the best fishing grounds in the Maldives, as well as beautiful coral reefs for snorkeling and diving."]},{"heading":"Henbandhoo: Natural Beauty & Marine Life","paragraphs":["Henbandhoo Island is renowned for its stunning natural beauty, featuring powdery white sand beaches, crystal-clear waters, and vibrant marine ecosystems. The island offers an unspoiled tropical paradise perfect for relaxation and exploration."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Henbandhoo boasts some of the most beautiful beaches in Noonu Atoll, with soft white sand and crystal-clear waters perfect for swimming and relaxation."]},{"heading":"Excellent Snorkeling","paragraphs":["The island''s house reef features diverse marine life, colorful corals, and excellent visibility, accessible directly from the beach."]},{"heading":"Authentic Island Culture","paragraphs":["Experience genuine Maldivian hospitality and traditional island life in a peaceful setting away from commercial tourism."]},{"heading":"Sandbank Excursions","paragraphs":["Explore nearby uninhabited sandbanks for the ultimate desert island experience with picnics and swimming in crystal-clear waters."]},{"heading":"Beach Highlights","paragraphs":["Henbandhoo''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Henbandhoo offers a variety of activities focused on marine adventures, cultural experiences, and natural exploration in a pristine environment."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals and tropical fish."]},{"heading":"Scuba Diving","paragraphs":["Discover world-class dive sites around Noonu Atoll with professional dive operators."]},{"heading":"Island Hopping","paragraphs":["Visit nearby islands and discover uninhabited sandbanks with pristine natural beauty."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for authentic night fishing experiences using traditional methods."]},{"heading":"Cultural Experiences","paragraphs":["Immerse yourself in local community life and authentic Maldivian customs."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching."]},{"heading":"People & Community Life","paragraphs":["Henbandhoo is home to a close-knit community of approximately 600 residents who maintain traditional Maldivian ways of life. The island''s population is known for their warmth and hospitality."]},{"heading":"Daily Life","paragraphs":["Life on Henbandhoo follows natural island rhythms, with fishing and community activities central to daily life. The island maintains a peaceful, unhurried pace that reflects traditional values."]},{"heading":"Culture & Traditions","paragraphs":["Henbandhoo preserves authentic Maldivian cultural traditions including music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm."]},{"heading":"Local Economy","paragraphs":["The island''s economy is based on fishing and increasingly tourism, with families engaging in traditional occupations while participating in the growing tourism sector."]}],"island_faqs":[{"question":"How do I get to Henbandhoo Island?","answer":"Henbandhoo can be reached by domestic flight to Maafaru Airport (55 minutes from Male) followed by a 30-minute speedboat ride. Seaplane transfers are also available but depend on weather conditions."},{"question":"What is the best time to visit Henbandhoo?","answer":"The best time is during the dry season from December to April when weather is most favorable, though the island can be visited year-round."}],"island_nearby_slugs":["foddhoo","manadhoo","velidhoo","miladhoo","maafaru","landhoo","kendhikolhudhoo","magoodhoo","kudafaree","lhohi","maalhendhoo"]}'::jsonb
where node_type = 'location' and slug = 'henbandhoo';


-- himandhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Himandhoo Island from Male?","answer":"You can reach Himandhoo Island from Male by public ferry or speedboat. The public ferry operates three times a week (Sunday, Tuesday, and Thursday), departing from Male at 9:00 AM and arriving at Himandhoo around 2:00 PM. Some guesthouses also offer private transfers for a higher fee."},{"question":"What is the best time to visit Himandhoo Island?","answer":"The best time to visit Himandhoo Island is during the dry season from November to April when the weather is sunny with minimal rainfall and calm seas. The peak tourist season is from December to March, offering optimal conditions for beach activities and water sports. The wet season (May to October) sees occasional rain showers and slightly rougher seas, but still has many sunny days and lower prices. For the best balance of good weather and fewer crowds, consider visiting in November or April."},{"question":"Can I visit the historical mosque on Himandhoo Island?","answer":"Yes, visitors can view the historical Medhuziyaaraiy (Old Friday Mosque) on Himandhoo Island, but there are some important considerations. As it is an active place of worship, visitors should dress modestly (covering shoulders and knees), remove shoes before entering, and ask permission from local authorities or your guesthouse host before visiting. Photography may be restricted inside the mosque. It''s best to visit with a local guide who can explain the historical and cultural significance of this important site and ensure that proper protocols are followed."},{"question":"Are there any dress code requirements on Himandhoo Island?","answer":"Yes, as Himandhoo is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas. Both men and women should cover shoulders and knees when walking around the village, visiting shops, or dining in local restaurants. Swimwear (including bikinis) is only permitted at the designated \"bikini beach\" area. When visiting the mosque or religious sites, women should cover their heads with a scarf. These dress code requirements are a sign of respect for local culture and traditions."},{"question":"What activities are available on Himandhoo Island?","answer":"Himandhoo Island offers a variety of activities for visitors including snorkeling on the house reef, historical and cultural tours, traditional fishing trips, dolphin watching excursions, island hopping to nearby islands, sandbank picnics, and cooking classes. Water sports like kayaking and paddleboarding are available through some guesthouses. Cultural experiences include Boduberu (traditional drumming) performances, handicraft demonstrations, and historical site visits. Most activities can be arranged through your accommodation or local tour operators on the island."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'himandhoo';


-- himmafushi
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, North Male Atoll"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,000 residents"},{"label":"Size","value":"0.6 km long, 0.3 km wide"},{"label":"Distance from Male","value":"20 km"},{"label":"Transfer Options","value":"Public ferry, speedboat"},{"label":"Known For","value":"Excellent surfing, beautiful beaches, authentic culture"},{"label":"Best For","value":"Surfers, adventure seekers, budget travelers"}],"island_overview":["Located in the Kaafu Atoll approximately 20 kilometers north of Male, Himmafushi Island offers visitors an authentic Maldivian experience with the added thrill of excellent surfing conditions. This vibrant island maintains its traditional character while providing excellent facilities for tourists seeking both adventure and cultural immersion in the Maldives.","What makes Himmafushi special is its reputation as one of the best surfing spots in the Maldives, combined with its authentic local island atmosphere. The island features beautiful beaches with powdery white sand and crystal-clear turquoise waters. The surrounding waters offer consistent surf breaks that attract surfers from around the world.","Visitors to Himmafushi are drawn by its surf culture, excellent marine life, authentic cultural experiences, and budget-friendly accommodations. The island''s strategic location provides easy access to Male while offering a peaceful retreat with a distinct local character."],"island_sections":[{"heading":"Location & Map","paragraphs":["Himmafushi Island is situated in the northern part of Kaafu Atoll (North Male Atoll), approximately 20 kilometers from Male. This location provides excellent access to both the capital and the best surf breaks in the area while maintaining the peaceful atmosphere of a traditional Maldivian island.","The island''s position offers protection from strong currents while still providing access to excellent surfing spots and snorkeling sites. The surrounding waters feature consistent waves that attract surfers of all levels, from beginners to advanced riders."]},{"heading":"Himmafushi: Surfing Paradise & Natural Beauty","paragraphs":["Himmafushi Island is renowned for its surf breaks and natural beauty, featuring pristine beaches and healthy coral reefs. The island offers visitors an exciting tropical paradise with excellent waves and abundant marine life."]},{"heading":"World-Class Surfing","paragraphs":["Himmafushi boasts some of the best surf breaks in the Maldives, with consistent waves suitable for all levels of surfers. The famous \"Jailbreak\" surf spot is just a short boat ride away."]},{"heading":"Beautiful White Sand Beaches","paragraphs":["The island features stunning white sand beaches with crystal-clear turquoise waters, offering the perfect setting for relaxation when you''re not catching waves."]},{"heading":"Excellent Snorkeling","paragraphs":["When the surf is flat, explore the vibrant house reef accessible from shore, featuring diverse marine life and coral formations perfect for snorkeling."]},{"heading":"Surf Culture & Local Life","paragraphs":["Experience the unique blend of Maldivian culture and surf lifestyle, with opportunities to interact with friendly locals and fellow surf enthusiasts."]},{"heading":"Surfing Highlights","paragraphs":["Himmafushi''s surf scene offers:"]},{"heading":"Marine Environment","paragraphs":["The island''s marine ecosystem features:"]},{"heading":"Activities & Experiences","paragraphs":["Himmafushi offers a variety of activities focused on surfing, marine adventures, and cultural experiences. The island''s surf culture and pristine environment provide excellent opportunities for both adrenaline and relaxation."]},{"heading":"Surfing","paragraphs":["Ride world-class waves at famous breaks like Jailbreak, Sultans, and Honky''s, suitable for all levels from beginner to advanced."]},{"heading":"Snorkeling","paragraphs":["Explore the vibrant house reef directly from shore or join boat excursions to nearby coral gardens and marine sanctuaries."]},{"heading":"Scuba Diving","paragraphs":["Discover underwater wonders at nearby dive sites with professional dive operators offering courses and guided dives."]},{"heading":"Sandbank Visits","paragraphs":["Experience pristine uninhabited sandbanks for picnics, swimming, and the ultimate desert island adventure."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for traditional night fishing experiences using hand lines under the starlit sky."]},{"heading":"Cultural Experiences","paragraphs":["Engage with local community life, learn traditional crafts, and experience authentic Maldivian hospitality."]},{"heading":"People & Community Life","paragraphs":["Himmafushi is home to a vibrant community of approximately 1,000 residents who have embraced both their traditional way of life and the island''s growing reputation as a surf destination. The island''s population is known for their exceptional hospitality, strong community bonds, and welcoming attitude toward visitors."]},{"heading":"Daily Life","paragraphs":["Life on Himmafushi follows traditional Maldivian rhythms, beginning with morning prayers and continuing with fishing, tourism-related work, and community activities. The island maintains a unique atmosphere where traditional values coexist with the energetic vibe of surf culture. Fishing remains an important livelihood alongside tourism services."]},{"heading":"Culture & Traditions","paragraphs":["Himmafushi preserves authentic Maldivian cultural traditions including traditional music, dance, and crafts. The community celebrates Islamic festivals with enthusiasm and maintains traditional practices such as boat building, fishing techniques, and local cuisine preparation. Visitors can often observe or participate in cultural activities."]},{"heading":"Surf Community","paragraphs":["The island has developed a special surf community that welcomes visitors from around the world. Local surfers are often happy to share their knowledge of the best breaks, and several surf schools operate on the island, providing lessons and equipment rental for visitors."]}],"island_faqs":[{"question":"How do I get to Himmafushi Island?","answer":"Himmafushi Island can be reached by public ferry or speedboat from Male. Many surf-focused accommodations can arrange specialized transfers for surfers with equipment."},{"question":"What is the best time to visit Himmafushi for surfing?","answer":"The best time to visit Himmafushi for surfing is during the southwest monsoon from April to October when consistent swells produce the best waves. The peak surf season runs from June to September with the biggest and most consistent waves. However, the island offers good surfing conditions year-round, with smaller but cleaner waves during the northeast monsoon (November-March) that may be better for beginners."},{"question":"What accommodation options are available on Himmafushi?","answer":"Himmafushi offers various budget-friendly and mid-range accommodations including family-run guesthouses, surf-focused lodges, and beachfront properties. Many properties cater specifically to surfers with features like board storage, repair services, and surf trip arrangements. Most accommodations offer air conditioning, private bathrooms, meal packages, and can arrange tours and transfers."},{"question":"What surfing facilities are available on Himmafushi?","answer":"Himmafushi offers excellent surfing facilities including surf schools with experienced instructors, board rental shops (shortboards, longboards, and funboards), repair services, and daily boat transfers to the best breaks. Several guesthouses specialize in surf packages that include accommodation, meals, and daily surf trips. The island has a vibrant surf community with local knowledge about conditions and breaks."}],"island_nearby_slugs":["huraa","dhiffushi","maafushi","gulhi","guraidhoo","hulhumale","male","kaashidhoo","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'himmafushi';


-- hinnavaru
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Lhaviyani Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,200 residents"},{"label":"Size","value":"1.2 km long, 0.5 km wide"},{"label":"Distance from Male","value":"140 km"},{"label":"Known For","value":"Fishing culture, beautiful beaches, authentic experiences"},{"label":"Best For","value":"Culture seekers, budget travelers, fishing enthusiasts"}],"island_overview":["Nestled in the pristine waters of Lhaviyani Atoll, Hinnavaru Island offers visitors a genuine glimpse into traditional Maldivian island life. This charming fishing village maintains its authentic character while welcoming travelers with warm hospitality.","Hinnavaru is known for its long sandy beaches, excellent fishing culture, and laid-back island atmosphere. The island provides a perfect balance between traditional Maldivian lifestyle and modern tourist facilities.","What makes Hinnavaru special is its strong community spirit, excellent marine environment, and the opportunity to experience authentic island culture away from crowded tourist resorts."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hinnavaru Island is located in the northern part of Lhaviyani Atoll, approximately 140 kilometers from Male. This location offers easy access to some of the best dive sites in the Maldives while maintaining a peaceful island atmosphere.","The island''s position provides excellent fishing grounds and access to beautiful coral reefs. Hinnavaru is close to several resort islands, allowing visitors to combine local island experiences with luxury resort amenities."]},{"heading":"Hinnavaru: Natural Beauty & Marine Life","paragraphs":["Hinnavaru Island boasts stunning natural beauty with long stretches of white sand beaches, crystal-clear lagoons, and healthy coral reefs teeming with marine life."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Hinnavaru features some of the longest natural beaches in Lhaviyani Atoll, perfect for sunbathing and beach walks."]},{"heading":"Excellent Snorkeling","paragraphs":["The island''s house reef offers easy access to colorful coral formations and diverse marine life."]},{"heading":"Authentic Fishing Culture","paragraphs":["Experience the traditional fishing lifestyle that has sustained Hinnavaru for generations."]},{"heading":"Nearby Sandbanks","paragraphs":["Visit pristine uninhabited sandbanks for the ultimate tropical island experience."]},{"heading":"Beach Highlights","paragraphs":["Hinnavaru''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Hinnavaru offers a variety of activities focused on marine adventures, cultural experiences, and relaxation."]},{"heading":"Snorkeling Adventures","paragraphs":["Explore vibrant coral reefs teeming with tropical fish and marine life."]},{"heading":"Scuba Diving","paragraphs":["Discover world-class dive sites in Lhaviyani Atoll."]},{"heading":"Island Hopping","paragraphs":["Visit nearby islands and resorts to experience different aspects of the Maldives."]},{"heading":"Fishing Excursions","paragraphs":["Join local fishermen for traditional fishing experiences."]},{"heading":"Cultural Experiences","paragraphs":["Learn about traditional Maldivian crafts, music, and daily life."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy breathtaking sunsets over the Indian Ocean."]},{"heading":"People & Community Life","paragraphs":["Hinnavaru is home to a vibrant community of approximately 1,200 residents who maintain traditional Maldivian ways of life while embracing modern development."]},{"heading":"Daily Life","paragraphs":["Life on Hinnavaru revolves around fishing, tourism, and community activities. The island has a strong fishing heritage and many residents continue this traditional occupation."]},{"heading":"Culture & Traditions","paragraphs":["Hinnavaru preserves authentic Maldivian cultural traditions including traditional music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm."]}],"island_faqs":[{"question":"How do I get to Hinnavaru Island?","answer":"There''s also a public ferry option that takes 6-8 hours."},{"question":"What is the best time to visit Hinnavaru?","answer":"The best time is during the dry season from December to April, but Hinnavaru can be visited year-round."}],"island_nearby_slugs":["kurendhoo","naifaru","olhuvelifushi"]}'::jsonb
where node_type = 'location' and slug = 'hinnavaru';


-- hirilandhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Thaa Atoll, Central Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 2,100 residents"},{"label":"Size","value":"1.8 km long, 1.1 km wide"},{"label":"Distance from Male","value":"210 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Spectacular culture, stunning beaches, excellent snorkeling"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, snorkelers, adventure seekers"}],"island_overview":["Hirilandhoo Island is a spectacular local island in Thaa Atoll that offers visitors a vibrant glimpse into traditional Maldivian life. This remarkable island combines natural beauty with an energetic atmosphere, providing an ideal destination for travelers seeking exciting cultural experiences and stunning tropical surroundings.","Known for its gorgeous beaches, spectacular coral reefs, and excellent marine biodiversity, Hirilandhoo provides wonderful opportunities for snorkeling, swimming, and underwater exploration. The island''s vibrant community embraces visitors with traditional Maldivian warmth and shares their dynamic way of life with spectacular hospitality.","What makes Hirilandhoo special is its spectacular natural environment and vibrant island setting. Visitors can enjoy stunning beaches, explore rich marine ecosystems, and experience dynamic island culture while staying in comfortable accommodations that showcase the spectacular Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hirilandhoo Island is beautifully located in the central part of Thaa Atoll, approximately 210 kilometers from Male. This location provides a spectacular and vibrant experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to stunning coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Thaa Atoll in its most spectacular form."]},{"heading":"Hirilandhoo: Spectacular Paradise & Marine Excellence","paragraphs":["Hirilandhoo Island is blessed with exceptional natural beauty, featuring stunning white sand beaches, crystal-clear turquoise waters, and one of the most spectacular marine environments in Thaa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a vibrant, dynamic setting."]},{"heading":"Stunning White Sand Beaches","paragraphs":["Hirilandhoo features spectacular white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and dynamic beach activities."]},{"heading":"Spectacular House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers vibrant snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Vibrant Island Community","paragraphs":["Experience the dynamic spirit of traditional island life with friendly locals and spectacular Maldivian culture in a vibrant community setting."]},{"heading":"Dynamic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and stunning islands around Hirilandhoo for spectacular tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Hirilandhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Hirilandhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Hirilandhoo offers a perfect blend of marine adventures, cultural experiences, and spectacular activities. The island''s vibrant environment and dynamic atmosphere provide ideal conditions for various activities in a stunning, energetic setting."]},{"heading":"Spectacular House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in spectacular waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby stunning dive sites with professional dive operators offering guided dives and certification courses in spectacular marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, stunning sandbanks, and discover the natural beauty of Thaa Atoll with vibrant exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in spectacular community settings."]},{"heading":"Dynamic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience spectacular Maldivian island life with vibrant cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy stunning sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in spectacular waters."]},{"heading":"Community Life & Culture","paragraphs":["Hirilandhoo is home to approximately 2,100 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and spectacular cultural traditions that create a vibrant atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Hirilandhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains a spectacular atmosphere where visitors can experience vibrant Maldivian culture and customs in their most dynamic, energetic setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this spectacular island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Hirilandhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and spectacular cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Hirilandhoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Thaa Atoll."},{"question":"What is the best time to visit Hirilandhoo?","answer":"The best time to visit Hirilandhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more spectacular local atmosphere."},{"question":"What accommodation options are available on Hirilandhoo?","answer":"Hirilandhoo offers various accommodations including spectacular guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a vibrant setting."},{"question":"What makes Hirilandhoo''s vibrancy special?","answer":"Hirilandhoo is known for its spectacular and vibrant natural environment. The island maintains traditional Maldivian cultural practices while offering a dynamic atmosphere perfect for energetic exploration. Visitors can experience exciting cultural exchanges and participate in spectacular community activities."}],"island_nearby_slugs":["guraidhoo","gaadhiffushi","dhiyamigili","burunee","vilufushi","veymandoo","vandhoo","thimarafushi","omadhoo","madifushi","kinbidhoo","kandoodhoo"]}'::jsonb
where node_type = 'location' and slug = 'hirilandhoo';


-- hirimaradhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Hirimaradhoo Island?","answer":"Due to the island''s remote location in the northern atolls, direct public ferry services from Male are limited. Most guesthouses can arrange the complete transfer from Male, including the domestic flight and speedboat connection. When planning your journey, remember that weather conditions can occasionally affect flight schedules in this region, so it''s advisable to allow buffer days in your travel plans. The journey to Hirimaradhoo is part of the adventure, offering beautiful aerial views of the Maldivian atolls during the flight and a chance to experience the stunning blue waters during the speedboat transfer."},{"question":"What makes Hirimaradhoo''s weaving traditions unique in the Maldives?","answer":"Hirimaradhoo''s weaving traditions stand out in the Maldives because the island has preserved comprehensive knowledge of traditional textile arts that combine various techniques while maintaining distinctly Maldivian characteristics. The island is particularly known for its \"thundu kunaa\" (fine mat weaving) that features intricate geometric patterns and designs that often tell stories or represent aspects of island life. Hirimaradhoo weavers maintain exceptional skill in creating these mats, which require months of meticulous work and precise technique. The island''s artisans have preserved knowledge of natural dyes derived from plants, minerals, and sometimes marine sources, creating a palette of colors that are both beautiful and environmentally sustainable. What makes Hirimaradhoo special is the integration of practical function with artistic expression, as even everyday items are created with attention to aesthetic detail and cultural significance. The community maintains specialized techniques for preparing materials, including methods for harvesting, drying, and processing various plant fibers to achieve specific qualities in the finished textiles. Hirimaradhoo is also known for its pattern-making traditions, with some families maintaining unique designs that have been passed down for generations and serve as a form of cultural identity. These preserved traditions offer visitors insights into a sophisticated artistic tradition that connects to centuries of Maldivian cultural heritage while demonstrating remarkable adaptation to the materials available in the island environment."},{"question":"What is the best time to visit Hirimaradhoo Island?","answer":"The best time to visit Hirimaradhoo Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. This period is ideal for water activities, with excellent visibility for snorkeling and diving. For those interested in experiencing the island''s weaving traditions, this dry season is also excellent as many artisanal activities take place outdoors, and materials like palm leaves and plant fibers are harvested and processed during this period. The southwest monsoon (May to November) brings occasional rain showers but also lower prices and fewer tourists. This season can still be good for cultural experiences and indoor weaving demonstrations, though some outdoor activities may be affected by rain. Water temperature remains warm (27-30C/80-86F) throughout the year. Due to Hirimaradhoo''s northern location, it may experience slightly different weather patterns than southern atolls, with the possibility of brief rain showers even during the dry season. The shoulder months of November and April often offer a good balance of favorable weather and lower visitor numbers."},{"question":"What type of accommodation can I expect on Hirimaradhoo?","answer":"Accommodation on Hirimaradhoo is limited and simple, reflecting the island''s authentic character and minimal tourism development. The island offers a small number of family-run guesthouses that provide clean, comfortable rooms with basic amenities including air conditioning, private bathrooms with hot water, and Wi-Fi (though connectivity may be inconsistent). Most accommodations offer full-board packages that include three home-cooked Maldivian meals daily, featuring fresh seafood caught by local fishermen. Some weaving families also offer homestay experiences where guests stay in a room within a family home, providing deeper cultural immersion and the opportunity to observe traditional textile arts up close. A few properties are located near the beach, offering easy access to the island''s beautiful shores. Luxury amenities are limited, and the focus is on authentic experiences rather than high-end facilities. What these accommodations lack in luxury, they make up for in personal service, cultural insights, and genuine hospitality. Visitors should adjust their expectations accordingly and embrace the opportunity to experience authentic island life rather than expecting resort-style amenities."},{"question":"Can I participate in weaving activities as a visitor to Hirimaradhoo?","answer":"Yes, visitors to Hirimaradhoo have excellent opportunities to participate in weaving activities, which is one of the island''s unique attractions. Most guesthouses can arrange for guests to join workshops where you can learn basic weaving techniques from skilled local artisans. These hands-on experiences allow you to create simple items like small mats, coasters, or decorative pieces while learning about the cultural significance of different patterns and designs. Material preparation demonstrations show how plants are harvested, processed, and prepared for weaving, from initial collection to the final stages before weaving begins. Pattern-making sessions provide insights into the geometric designs and motifs that characterize Maldivian textiles and their cultural meanings. For those with a deeper interest, extended workshops can sometimes be arranged where you can learn more advanced techniques or work on larger projects over several days. Some accommodations offer more immersive experiences where visitors can stay with weaving families, providing opportunities to observe and participate in the daily rhythm of this traditional craft. These activities provide not just entertainment but educational insights into an artisanal heritage that has shaped Maldivian material culture for centuries. The level of participation can be adjusted based on your interest and time available, from brief introductory sessions to more in-depth learning experiences."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'hirimaradhoo';


-- hithaadhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Dharavandhoo Island?","answer":"Seaplane transfers are available seasonally, while public ferry service operates weekly from Male (approximately 8 hours). Private speedboat transfers can also be arranged."},{"question":"When is the best time to see whale sharks and manta rays?","answer":"Whale sharks can be seen year-round in Dharavandhoo waters, with peak sightings from August to November. Manta rays are most abundant from May to November during the southwest monsoon, particularly in Hanifaru Bay. The best overall conditions for marine activities are typically from December to April."},{"question":"Do I need to be a certified diver to enjoy the marine life?","answer":"No, many of Dharavandhoo''s marine wonders can be experienced through snorkeling. The house reef offers excellent snorkeling directly from shore, and guided snorkel trips to Hanifaru Bay and whale shark areas are suitable for confident swimmers. For scuba diving, certification is required, but discover scuba programs are available for beginners."},{"question":"What makes Dharavandhoo different from other Maldivian islands?","answer":"Dharavandhoo''s unique combination of factors sets it apart: its location within a UNESCO Biosphere Reserve, reliable whale shark sightings year-round, proximity to Hanifaru Bay''s manta ray gatherings, domestic airport access, and blend of local culture with well-developed tourism infrastructure. Few islands offer this combination of marine life access and convenience."},{"question":"Are there any dress code requirements on Dharavandhoo?","answer":"As a local inhabited island with a Muslim population, modest dress is required in public areas (shoulders and knees covered). Swimwear is only permitted at the designated \"bikini beach.\" When visiting the mosque or religious sites, women should cover their heads. These requirements don''t apply during water activities or at resort day visits."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'hithaadhoo';


-- hithadhoo-seenu
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Seenu Atoll, Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 4,200 residents"},{"label":"Size","value":"2.8 km long, 1.5 km wide"},{"label":"Distance from Male","value":"541 km"},{"label":"Transfer Options","value":"Domestic flight to Gan Airport + speedboat"},{"label":"Known For","value":"Magnificent culture, stunning beaches, excellent fishing"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, fishing enthusiasts, adventure seekers"}],"island_overview":["Hithadhoo Island is a magnificent local island in Seenu Atoll that offers visitors a remarkable glimpse into traditional Maldivian life in the southernmost region of the archipelago. This outstanding island combines natural beauty with a splendid atmosphere, providing an ideal destination for travelers seeking exceptional cultural experiences and stunning tropical surroundings.","Known for its beautiful beaches, magnificent coral reefs, and excellent marine biodiversity, Hithadhoo provides wonderful opportunities for snorkeling, swimming, and underwater exploration. The island''s remarkable community embraces visitors with traditional Maldivian warmth and shares their outstanding way of life with magnificent hospitality.","What makes Hithadhoo special is its magnificent natural environment and remarkable southern location. Visitors can enjoy stunning beaches, explore rich marine ecosystems, and experience outstanding island culture while staying in comfortable accommodations that showcase the magnificent Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hithadhoo Island is magnificently located in the southern part of Seenu Atoll, approximately 541 kilometers from Male. This location provides a magnificent and remarkable experience as the southernmost inhabited island in the Maldives, while maintaining good accessibility through Gan International Airport.","The island''s position offers excellent protection from strong currents while providing access to stunning coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Seenu Atoll in its most magnificent form."]},{"heading":"Hithadhoo: Magnificent Paradise & Marine Splendor","paragraphs":["Hithadhoo Island is blessed with exceptional natural beauty, featuring stunning white sand beaches, crystal-clear turquoise waters, and one of the most magnificent marine environments in Seenu Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a remarkable, outstanding setting."]},{"heading":"Stunning White Sand Beaches","paragraphs":["Hithadhoo features magnificent white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and remarkable beach activities."]},{"heading":"Magnificent House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers outstanding snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Remarkable Island Community","paragraphs":["Experience the outstanding spirit of traditional southern island life with friendly locals and magnificent Maldivian culture in a remarkable community setting."]},{"heading":"Outstanding Fishing Heritage","paragraphs":["Discover the island''s rich fishing traditions and join local fishermen for magnificent fishing experiences in the abundant waters of Seenu Atoll."]},{"heading":"Beach Features","paragraphs":["Hithadhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Hithadhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Hithadhoo offers a perfect blend of marine adventures, cultural experiences, and magnificent activities. The island''s remarkable environment and outstanding atmosphere provide ideal conditions for various activities in a stunning, splendid setting."]},{"heading":"Magnificent House Reef Snorkeling","paragraphs":["Explore the outstanding house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in magnificent waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby stunning dive sites with professional dive operators offering guided dives and certification courses in magnificent marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, stunning sandbanks, and discover the natural beauty of Seenu Atoll with outstanding exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in magnificent community settings."]},{"heading":"Outstanding Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience magnificent Maldivian island life with remarkable cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy stunning sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in magnificent waters."]},{"heading":"Community Life & Culture","paragraphs":["Hithadhoo is home to approximately 4,200 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and magnificent cultural traditions that create a remarkable atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Hithadhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains a magnificent atmosphere where visitors can experience outstanding Maldivian culture and customs in their most remarkable, splendid setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this magnificent island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Hithadhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and magnificent cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Hithadhoo Island?","answer":"Regular inter-island ferry services are also available between Seenu Atoll islands."},{"question":"What is the best time to visit Hithadhoo?","answer":"The best time to visit Hithadhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more magnificent local atmosphere."},{"question":"What accommodation options are available on Hithadhoo?","answer":"Hithadhoo offers various accommodations including magnificent guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a remarkable setting."},{"question":"What makes Hithadhoo''s location special?","answer":"Hithadhoo is known for being the southernmost inhabited island in the Maldives, offering a magnificent and remarkable experience. The island maintains traditional Maldivian cultural practices while offering an outstanding atmosphere perfect for cultural exploration. Visitors can experience exceptional cultural exchanges and participate in magnificent community activities."}],"island_nearby_slugs":["feydhoo","maradhoo","hulhudhoo","hithadhoo"]}'::jsonb
where node_type = 'location' and slug = 'hithadhoo-seenu';


-- hithadhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Laamu Atoll, Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 800 residents"},{"label":"Size","value":"0.8 km long, 0.4 km wide"},{"label":"Distance from Male","value":"235 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat"},{"label":"Known For","value":"Pristine beaches, excellent snorkeling, peaceful atmosphere"},{"label":"Best For","value":"Nature lovers, snorkelers, cultural travelers, budget travelers"}],"island_overview":["Nestled in the pristine waters of Laamu Atoll, Hithadhoo Island represents the essence of authentic Maldivian island life. This charming local island offers visitors a unique opportunity to experience traditional culture while enjoying some of the most beautiful beaches in the southern Maldives.","Hithadhoo stands out for its untouched natural beauty, crystal-clear lagoons, and vibrant house reef that''s perfect for snorkeling. The island maintains its traditional character while welcoming visitors with genuine Maldivian hospitality and warmth.","What makes Hithadhoo truly special is its peaceful atmosphere, excellent marine life, and the opportunity to experience authentic island culture. Visitors can enjoy budget-friendly accommodations, delicious local cuisine, and unforgettable underwater adventures."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hithadhoo Island is strategically located in the southern part of Laamu Atoll, approximately 235 kilometers from Male. This remote location ensures an authentic and peaceful experience, far from the bustling tourist areas, while still offering excellent accessibility.","The island''s position provides natural protection from strong currents while maintaining access to some of the best snorkeling and diving sites in the Maldives. The surrounding waters feature healthy coral reefs and abundant marine life."]},{"heading":"Hithadhoo: Natural Beauty & Marine Wonders","paragraphs":["Hithadhoo Island is renowned for its exceptional natural beauty, featuring powder-white sand beaches, crystal-clear turquoise waters, and one of the most vibrant house reefs in Laamu Atoll. The island offers an unspoiled tropical paradise perfect for relaxation and marine exploration."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Hithadhoo boasts some of the most beautiful beaches in Laamu Atoll, with soft white sand and crystal-clear waters perfect for swimming and sunbathing."]},{"heading":"World-Class Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and features diverse marine life, colorful corals, and excellent underwater visibility."]},{"heading":"Authentic Island Culture","paragraphs":["Experience genuine Maldivian hospitality and traditional island life in a peaceful setting away from commercial tourism."]},{"heading":"Pristine Sandbank Visits","paragraphs":["Explore nearby uninhabited sandbanks for the ultimate desert island experience with picnics and swimming in crystal-clear waters."]},{"heading":"Beach Highlights","paragraphs":["Hithadhoo''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Hithadhoo offers an excellent variety of activities focused on marine adventures, cultural experiences, and natural exploration. The island''s pristine environment provides perfect opportunities for both adventure and relaxation."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility."]},{"heading":"Scuba Diving Adventures","paragraphs":["Discover world-class dive sites around Laamu Atoll with professional dive operators offering courses and guided dives."]},{"heading":"Island Hopping Tours","paragraphs":["Visit nearby islands and discover uninhabited sandbanks, each offering unique experiences and pristine natural beauty."]},{"heading":"Traditional Night Fishing","paragraphs":["Join local fishermen for authentic night fishing experiences using traditional hand lines under the starlit Maldivian sky."]},{"heading":"Cultural Experiences","paragraphs":["Immerse yourself in local community life, learn traditional crafts, and experience authentic Maldivian customs and traditions."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing."]},{"heading":"People & Community Life","paragraphs":["Hithadhoo is home to a close-knit community of approximately 800 residents who have preserved traditional Maldivian ways of life for generations. The island''s population is renowned for their warmth, hospitality, and strong community bonds."]},{"heading":"Daily Life","paragraphs":["Life on Hithadhoo follows the natural rhythms of island living, beginning with morning prayers and continuing with fishing, community work, and family activities. The island maintains a peaceful, unhurried pace that reflects traditional Maldivian values."]},{"heading":"Culture & Traditions","paragraphs":["Hithadhoo preserves authentic Maldivian cultural traditions including traditional music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm and maintains traditional practices such as dhoni building and traditional fishing techniques."]},{"heading":"Local Economy","paragraphs":["The island''s economy is primarily based on fishing and increasingly tourism. Many families engage in traditional occupations while also participating in the growing tourism sector through guesthouses, restaurants, and tour services."]}],"island_faqs":[{"question":"How do I get to Hithadhoo Island?","answer":"Hithadhoo Island can be reached by domestic flight to Kadhdhoo Airport (1 hour from Male) followed by a 25-minute speedboat ride. Seaplane transfers are also available but depend on weather conditions. There''s also a weekly public ferry from Male that takes 14-16 hours."},{"question":"What is the best time to visit Hithadhoo?","answer":"The best time to visit Hithadhoo is during the dry season from December to April when weather conditions are most favorable. However, the island can be visited year-round, with the wet season (May-November) offering fewer crowds and lower accommodation rates."},{"question":"What accommodation options are available on Hithadhoo?","answer":"Hithadhoo offers various budget-friendly and mid-range accommodations including family guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages."},{"question":"What activities are available on Hithadhoo?","answer":"Hithadhoo offers excellent snorkeling from the house reef, diving excursions, island hopping tours, cultural experiences, traditional fishing trips, and sunset cruises. The island is particularly known for its pristine marine environment and authentic cultural experiences."}],"island_nearby_slugs":["fonadhoo","gan","maabaidhoo","mundoo","isdhoo","kunahandhoo","dhanbidhoo","maamendhoo","maavah"]}'::jsonb
where node_type = 'location' and slug = 'hithadhoo';


-- hoandeddhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Faresmaathodaa Island?","answer":"Public ferry service operates weekly from Male (approximately 18-20 hours journey time). Private speedboat transfers can be arranged through guesthouses (approximately 7.5 hours from Male)."},{"question":"What is the best time to visit Faresmaathodaa Island?","answer":"The best time to visit Faresmaathodaa Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. For whale shark encounters, visit during the southwest monsoon (May to December). Water temperature remains warm (27-30C/80-86F) throughout the year."},{"question":"What makes Faresmaathodaa different from other local islands in the Maldives?","answer":"Faresmaathodaa stands out for its exceptional preservation of traditional Maldivian life in a remote setting and its unique twin-island structure. Unlike most Maldivian islands, Faresmaathodaa consists of two separate islands connected by a small bridge, creating a distinctive figure-eight shape. This unique geography provides additional shoreline and beach access, while the channel between the islands creates a natural harbor and a special marine environment."},{"question":"Can I walk between the two parts of Faresmaathodaa Island?","answer":"Yes, the two parts of Faresmaathodaa Island are connected by a small bridge that allows easy pedestrian access between them. Walking across this bridge is actually a popular activity for visitors, as it offers excellent views of the channel and surrounding waters. The bridge has become a gathering spot for locals and visitors alike, especially during sunset when the views are particularly spectacular."},{"question":"What marine life can I expect to see while snorkeling around Faresmaathodaa?","answer":"Faresmaathodaa''s waters offer excellent marine biodiversity, including healthy coral formations with both hard and soft corals. Common sightings include reef sharks (particularly blacktip and whitetip), sea turtles, various ray species, and abundant reef fish. The channel between the two parts of the island creates a unique marine environment with different currents and marine life. Seasonal visitors include whale sharks (May-December) and manta rays. The house reef provides easy access to this underwater world directly from shore."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'hoandeddhoo';


-- holhudhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Noonu Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 800 residents"},{"label":"Size","value":"0.9 km long, 0.5 km wide"},{"label":"Distance from Male","value":"175 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Traditional culture, beautiful beaches, excellent snorkeling"},{"label":"Best For","value":"Cultural enthusiasts, beach lovers, snorkelers, budget travelers"}],"island_overview":["Holhudhoo Island is a charming local island in Noonu Atoll that perfectly embodies the authentic spirit of traditional Maldivian life. This peaceful island offers visitors an intimate glimpse into genuine island culture while providing access to some of the most beautiful beaches and marine environments in the northern Maldives.","Known for its friendly community, pristine beaches, and excellent house reef, Holhudhoo provides an ideal setting for travelers seeking authentic cultural experiences combined with natural beauty. The island maintains its traditional character while offering comfortable accommodations and warm hospitality.","What makes Holhudhoo special is its perfect balance of cultural authenticity and natural splendor. Visitors can enjoy stunning beaches, explore vibrant marine life, and experience traditional island life while staying in comfortable, locally-run accommodations that showcase genuine Maldivian hospitality."],"island_sections":[{"heading":"Location & Map","paragraphs":["Holhudhoo Island is strategically positioned in the northern part of Noonu Atoll, approximately 175 kilometers from Male. This location provides an authentic island experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s location offers excellent protection from strong currents while providing access to pristine coral reefs and diverse marine ecosystems. Its position in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Noonu Atoll."]},{"heading":"Holhudhoo: Natural Beauty & Cultural Heritage","paragraphs":["Holhudhoo Island is blessed with exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and a vibrant marine environment. The island offers perfect conditions for beach relaxation and marine exploration in an authentic cultural setting."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Holhudhoo features stunning white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and beach activities."]},{"heading":"Excellent House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers exceptional snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Authentic Cultural Experiences","paragraphs":["Experience traditional Maldivian island life with friendly locals and authentic cultural practices in a genuine community setting."]},{"heading":"Pristine Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and pristine islands around Holhudhoo for ultimate tropical paradise experiences."]},{"heading":"Beach Features","paragraphs":["Holhudhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Holhudhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Holhudhoo offers a perfect blend of marine adventures, cultural experiences, and community activities. The island''s traditional environment and authentic atmosphere provide ideal conditions for various activities in a genuine cultural setting."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby excellent dive sites with professional dive operators offering guided dives and certification courses."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, pristine sandbanks, and discover the beauty of Noonu Atoll with authentic exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips."]},{"heading":"Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience authentic Maldivian island life."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing."]},{"heading":"Community Life & Culture","paragraphs":["Holhudhoo is home to approximately 800 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and cultural traditions that create a welcoming atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Holhudhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains an authentic atmosphere where visitors can experience genuine Maldivian culture and customs in their most traditional setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations."]},{"heading":"Sustainable Tourism","paragraphs":["Holhudhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and cultural heritage for future generations."]}],"island_faqs":[{"question":"How do I get to Holhudhoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Noonu Atoll."},{"question":"What is the best time to visit Holhudhoo?","answer":"The best time to visit Holhudhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and more authentic local atmosphere."},{"question":"What accommodation options are available on Holhudhoo?","answer":"Holhudhoo offers various budget-friendly accommodations including traditional guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages."},{"question":"What makes Holhudhoo''s community special?","answer":"Holhudhoo is known for its traditional and authentic community atmosphere. The island maintains genuine Maldivian cultural practices while welcoming visitors with warm hospitality. Visitors can experience authentic cultural exchanges and participate in traditional community activities."}],"island_nearby_slugs":["foddhoo","manadhoo","velidhoo","miladhoo","maafaru","landhoo","kendhikolhudhoo","magoodhoo","henbandhoo","kudafaree","lhohi","maalhendhoo"]}'::jsonb
where node_type = 'location' and slug = 'holhudhoo';


-- hulhudheli
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Hulhudheli Island?","answer":"Public ferry service operates weekly from Male (approximately 10-12 hours journey time). Private speedboat transfers can be arranged through guesthouses (approximately 4-5 hours from Male). Most accommodations can assist with arranging transportation."},{"question":"What is the best time to visit Hulhudheli Island?","answer":"The best time to visit Hulhudheli Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas. This period is ideal for water activities, with excellent visibility for snorkeling and diving. The southwest monsoon (May to November) brings occasional rain showers but also lower prices and fewer tourists. Water temperature remains warm (27-30C/80-86F) throughout the year."},{"question":"What makes Hulhudheli different from other local islands in the Maldives?","answer":"Hulhudheli stands out for its exceptional preservation of traditional Maldivian life in Dhaalu Atoll. Unlike more developed islands, Hulhudheli maintains its authentic character with a community still primarily engaged in traditional fishing and crafts. The island offers access to Dhaalu Atoll''s spectacular marine life while providing a genuine cultural experience away from mass tourism. Its relatively small size creates an intimate atmosphere where visitors can truly connect with local culture and lifestyle."},{"question":"Are there any dress code requirements on Hulhudheli Island?","answer":"As Hulhudheli is a local inhabited island with a Muslim population, visitors are expected to dress modestly in public areas (shoulders and knees covered). Swimwear is only permitted at the designated \"bikini beach.\" When visiting the mosque or religious sites, women should cover their heads. These requirements don''t apply during water activities or at resort day visits. Respecting local dress codes is an important way to show cultural sensitivity during your stay."},{"question":"What marine life can I expect to see while snorkeling around Hulhudheli?","answer":"Hulhudheli''s waters offer excellent marine biodiversity, including healthy coral formations with both hard and soft corals. Common sightings include reef sharks (particularly blacktip and whitetip), sea turtles, various ray species, and abundant reef fish including parrotfish, angelfish, butterflyfish, and triggerfish. The house reef provides easy access to this underwater world directly from shore, while boat excursions can take you to nearby thilas (underwater pinnacles) that attract even more diverse marine life."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'hulhudheli';


-- hulhudhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Seenu Atoll (Addu Atoll), Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,200 residents"},{"label":"Size","value":"1.2 km long, 0.6 km wide"},{"label":"Distance from Male","value":"540 km"},{"label":"Transfer Options","value":"Domestic flight to Gan Airport"},{"label":"Known For","value":"Authentic culture, British-era heritage, beautiful beaches"},{"label":"Best For","value":"Cultural travelers, history enthusiasts, nature lovers"}],"island_overview":["Located in the southernmost atoll of the Maldives, Hulhudhoo Island offers visitors a unique blend of traditional Maldivian culture and stunning natural beauty. As part of the Addu Atoll (Seenu Atoll) region, Hulhudhoo boasts a distinct character shaped by its southern location.","The island is known for its lush vegetation, beautiful beaches, and friendly community. Unlike many northern islands, Hulhudhoo features unique characteristics including British-era infrastructure and a more temperate climate.","What makes Hulhudhoo special is its authentic atmosphere, where visitors can experience genuine island life while enjoying comfortable accommodations and excellent snorkeling opportunities."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hulhudhoo Island is part of the Addu City in Seenu Atoll, the southernmost atoll of the Maldives. This unique location gives the island distinct characteristics including a more temperate climate and British colonial influences.","The island is connected by causeways to neighboring islands, making it part of the largest connected island chain in the Maldives. This allows for easy exploration of the entire Addu Atoll region."]},{"heading":"Hulhudhoo: Natural Beauty & Marine Life","paragraphs":["Hulhudhoo Island is blessed with beautiful beaches, clear waters, and a unique marine environment shaped by its southern location in the Maldives."]},{"heading":"Beautiful Beaches","paragraphs":["Hulhudhoo boasts long stretches of white sand beaches with calm, clear waters perfect for swimming and relaxation."]},{"heading":"Marine Exploration","paragraphs":["The island''s house reef offers excellent snorkeling with diverse marine life and coral formations unique to southern atolls."]},{"heading":"Authentic Island Life","paragraphs":["Experience genuine Maldivian hospitality and traditions with a distinct southern character."]},{"heading":"Unique Ecosystems","paragraphs":["Explore the distinctive marine ecosystems of the southern atolls with guided excursions."]},{"heading":"Beach Highlights","paragraphs":["Hulhudhoo''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Hulhudhoo offers a variety of activities that showcase its unique southern atoll character and natural beauty."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef with unique southern atoll marine life."]},{"heading":"Scuba Diving","paragraphs":["Discover unique dive sites in the southern atolls with professional operators."]},{"heading":"Island Exploration","paragraphs":["Visit neighboring islands via causeways to experience different communities."]},{"heading":"Cultural Tours","paragraphs":["Learn about Hulhudhoo''s unique history and British-era heritage."]},{"heading":"Bicycle Tours","paragraphs":["Explore the connected islands by bicycle via the causeway network."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll''s unique geography."]},{"heading":"People & Community Life","paragraphs":["Hulhudhoo is home to a vibrant community of approximately 1,200 residents who maintain strong cultural traditions while embracing modern influences. The island''s population is known for their warmth and hospitality."]},{"heading":"Daily Life","paragraphs":["Life on Hulhudhoo follows traditional rhythms with fishing, craftsmanship, and family at its core. The connected nature of Addu Atoll allows for easy interaction between island communities."]},{"heading":"Culture & Traditions","paragraphs":["Hulhudhoo preserves authentic Maldivian culture with distinct southern influences. The island''s British-era heritage adds unique elements to its traditions and architecture."]},{"heading":"Local Economy","paragraphs":["The island''s economy is based on fishing, agriculture, and increasingly tourism. Many families participate in traditional occupations while also engaging in the tourism sector."]}],"island_faqs":[{"question":"How do I get to Hulhudhoo Island?","answer":"Hulhudhoo is accessible via domestic flight to Gan International Airport (1.5 hours from Male), followed by a short 15-minute speedboat ride or ferry transfer to the island."},{"question":"What makes Hulhudhoo different from northern islands?","answer":"Hulhudhoo has distinct southern characteristics including British-era heritage, a more temperate climate, and unique marine ecosystems. It''s also part of a connected island chain via causeways."},{"question":"What accommodation options are available?","answer":"Hulhudhoo offers various budget-friendly accommodations including family guesthouses and beachfront properties."},{"question":"What activities are unique to this area?","answer":"Unique activities include exploring British-era heritage sites, cycling across connected islands, and experiencing southern atoll marine life through snorkeling and diving."}],"island_nearby_slugs":["feydhoo","maradhoo","hithadhoo"]}'::jsonb
where node_type = 'location' and slug = 'hulhudhoo';


-- hulhudhuffaaru
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,000 residents"},{"label":"Size","value":"1.0 km long, 0.7 km wide"},{"label":"Distance from Male","value":"150 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Tranquil beaches, peaceful atmosphere, excellent snorkeling"},{"label":"Best For","value":"Peace seekers, beach lovers, snorkelers, relaxation enthusiasts"}],"island_overview":["Hulhudhuffaaru Island is a serene local island in Raa Atoll that offers visitors a peaceful glimpse into traditional Maldivian life. This tranquil island combines natural beauty with a calm atmosphere, providing an ideal destination for travelers seeking relaxing cultural experiences and unspoiled tropical serenity.","Known for its peaceful beaches, pristine coral reefs, and excellent marine biodiversity, Hulhudhuffaaru provides wonderful opportunities for snorkeling, swimming, and underwater exploration. The island''s gentle community embraces visitors with traditional Maldivian warmth and shares their peaceful way of life with serene hospitality.","What makes Hulhudhuffaaru special is its tranquil natural environment and peaceful island setting. Visitors can enjoy serene beaches, explore rich marine ecosystems, and experience calm island culture while staying in comfortable accommodations that showcase the peaceful Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hulhudhuffaaru Island is peacefully located in the northern part of Raa Atoll, approximately 150 kilometers from Male. This location provides a serene and tranquil experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to pristine coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Raa Atoll in a peaceful setting."]},{"heading":"Hulhudhuffaaru: Serene Paradise & Marine Tranquility","paragraphs":["Hulhudhuffaaru Island is blessed with exceptional natural beauty, featuring tranquil white sand beaches, crystal-clear turquoise waters, and one of the most peaceful marine environments in Raa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a serene, undisturbed setting."]},{"heading":"Tranquil White Sand Beaches","paragraphs":["Hulhudhuffaaru features peaceful white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and serene beach activities."]},{"heading":"Peaceful House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers serene snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Peaceful Island Community","paragraphs":["Experience the gentle spirit of traditional island life with friendly locals and peaceful Maldivian culture in a serene community setting."]},{"heading":"Serene Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and tranquil islands around Hulhudhuffaaru for peaceful tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Hulhudhuffaaru''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Hulhudhuffaaru feature:"]},{"heading":"Activities & Experiences","paragraphs":["Hulhudhuffaaru offers a perfect blend of marine adventures, cultural experiences, and peaceful activities. The island''s serene environment and tranquil atmosphere provide ideal conditions for various activities in a calm, undisturbed setting."]},{"heading":"Peaceful House Reef Snorkeling","paragraphs":["Explore the serene house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in tranquil waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby peaceful dive sites with professional dive operators offering guided dives and certification courses in serene marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, tranquil sandbanks, and discover the natural beauty of Raa Atoll with peaceful exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in peaceful community settings."]},{"heading":"Peaceful Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience gentle Maldivian island life with serene cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in tranquil waters."]},{"heading":"Community Life & Culture","paragraphs":["Hulhudhuffaaru is home to approximately 1,000 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and peaceful cultural traditions that create a serene atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Hulhudhuffaaru follows traditional patterns centered around fishing, family, and community activities. The island maintains a tranquil atmosphere where visitors can experience gentle Maldivian culture and customs in their most peaceful, undisturbed setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this serene island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Hulhudhuffaaru has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and peaceful cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Hulhudhuffaaru Island?","answer":"Regular ferry services are also available from Male and nearby islands in Raa Atoll."},{"question":"What is the best time to visit Hulhudhuffaaru?","answer":"The best time to visit Hulhudhuffaaru is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more peaceful local atmosphere."},{"question":"What accommodation options are available on Hulhudhuffaaru?","answer":"Hulhudhuffaaru offers various budget-friendly accommodations including serene guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a peaceful setting."},{"question":"What makes Hulhudhuffaaru''s atmosphere special?","answer":"Hulhudhuffaaru is known for its serene and peaceful atmosphere. The island maintains traditional Maldivian cultural practices while offering a tranquil environment perfect for relaxation. Visitors can experience gentle cultural exchanges and participate in community activities in this calm setting."}],"island_nearby_slugs":["rasgetheemu","ungoofaaru","rasmaadhoo","vaadhoo","alifushi","angolhitheemu","dhuvaafaru","fainu","inguraidhoo","innamaadhoo","kinolhas","maakurathu","maduvvaree","meedhoo"]}'::jsonb
where node_type = 'location' and slug = 'hulhudhuffaaru';


-- hulhumale
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, adjacent to Velana International Airport"},{"label":"Island Type","value":"Artificial Island"},{"label":"Population","value":"Approximately 50,000 residents"},{"label":"Size","value":"4.0 km long, 1.2 km wide"},{"label":"Distance from Airport","value":"7 km (connected by bridge)"},{"label":"Transfer Options","value":"Bus, taxi, walking bridge"},{"label":"Known For","value":"Modern infrastructure, airport connectivity, urban amenities"},{"label":"Best For","value":"Convenient stays, modern comfort, gateway access"}],"island_overview":["Located adjacent to Velana International Airport in Kaafu Atoll, Hulhumale Island stands as the Maldives'' most modern and accessible destination. This remarkable artificial island, reclaimed from the lagoon, represents the future of sustainable urban development in the Maldives while maintaining the natural beauty and tropical charm that makes the country so special.","What makes Hulhumale truly unique is its perfect combination of modern convenience and tropical paradise. As the closest inhabited island to the international airport, it serves as the ideal gateway for visitors while offering a complete Maldivian experience with beautiful beaches, excellent accommodations, diverse dining options, and easy access to activities throughout the atoll.","Visitors to Hulhumale are drawn by its unmatched convenience, modern infrastructure, beautiful artificial beaches, diverse accommodation options, and its role as the perfect base for exploring the Maldives. The island successfully combines urban amenities with tropical beauty, making it ideal for both short stopovers and extended stays."],"island_sections":[{"heading":"Location & Map","paragraphs":["Hulhumale Island enjoys the most convenient location in the Maldives, situated just 7 kilometers from Velana International Airport and connected by the Sinamale Bridge. This strategic position makes it the most accessible destination in the country, eliminating the need for boat transfers and providing immediate access to modern amenities upon arrival.","The island''s artificial nature allows for planned development with wide roads, modern infrastructure, and carefully designed public spaces. Despite being man-made, Hulhumale features beautiful artificial beaches, landscaped areas, and waterfront promenades that showcase the successful integration of urban planning with tropical aesthetics."]},{"heading":"Hulhumale: Modern Gateway & Urban Paradise","paragraphs":["Hulhumale Island represents the pinnacle of modern development in the Maldives, offering world-class infrastructure, urban conveniences, and contemporary amenities while maintaining the tropical beauty and relaxed atmosphere that defines the Maldivian experience."]},{"heading":"Unmatched Connectivity","paragraphs":["Direct connection to Velana International Airport via the Sinamale Bridge, making it the most accessible destination in the Maldives with no boat transfers required and immediate access upon arrival."]},{"heading":"Modern Urban Amenities","paragraphs":["Comprehensive urban infrastructure including shopping centers, restaurants, cafes, banks, hospitals, and recreational facilities that provide all modern conveniences in a tropical setting."]},{"heading":"Beautiful Artificial Beaches","paragraphs":["Carefully designed artificial beaches with pristine white sand, clear lagoons, and modern facilities that rival natural beaches while offering enhanced accessibility and amenities."]},{"heading":"Diverse Activities & Entertainment","paragraphs":["Wide range of activities from water sports and beach recreation to urban entertainment, shopping, dining, and cultural experiences that cater to all interests and preferences."]},{"heading":"Modern Infrastructure","paragraphs":["Hulhumale offers world-class urban amenities:"]},{"heading":"Urban Conveniences","paragraphs":["Comprehensive services and amenities available:"]},{"heading":"Activities & Experiences","paragraphs":["Hulhumale offers a unique blend of urban entertainment and tropical activities, providing diverse experiences that cater to all interests. The island''s modern infrastructure enables a wide range of activities while maintaining easy access to traditional Maldivian experiences."]},{"heading":"Beach & Water Activities","paragraphs":["Enjoy beautiful artificial beaches with water sports, swimming, sunbathing, and beachfront dining in a modern, well-maintained environment."]},{"heading":"Water Sports & Marine Activities","paragraphs":["Access to snorkeling, diving, jet skiing, and boat excursions with modern facilities and professional operators based on the island."]},{"heading":"Urban Entertainment","paragraphs":["Experience modern entertainment including shopping centers, restaurants, cafes, fitness centers, and recreational facilities in a tropical setting."]},{"heading":"Cultural & Educational Experiences","paragraphs":["Explore Maldivian culture through museums, cultural centers, and easy access to traditional islands and historical sites in Male."]},{"heading":"Island Hopping & Excursions","paragraphs":["Perfect base for exploring nearby islands, resorts, and atolls with convenient departure points and modern tour operators."]},{"heading":"Male City Access","paragraphs":["Easy access to Male, the capital city, for shopping, dining, historical sites, and experiencing urban Maldivian life and culture."]},{"heading":"People & Community Life","paragraphs":["Hulhumale is home to a diverse and dynamic community of approximately 50,000 residents, making it one of the most populous islands in the Maldives. This modern artificial island attracts people from across the country and internationally, creating a cosmopolitan atmosphere that blends traditional Maldivian values with contemporary urban living."]},{"heading":"Modern Urban Community","paragraphs":["The island represents the future of urban development in the Maldives, with a young, educated population that embraces both modernity and tradition. The community includes government workers, business professionals, students, and international residents, creating a vibrant multicultural environment that welcomes visitors from around the world."]},{"heading":"Planned Development","paragraphs":["Hulhumale showcases sustainable urban planning with green spaces, efficient infrastructure, and community facilities designed to enhance quality of life. The island serves as a model for future development in the Maldives, demonstrating how modern amenities can coexist with environmental consciousness and cultural preservation."]},{"heading":"Gateway Culture","paragraphs":["As the gateway to the Maldives, Hulhumale has developed a unique culture that bridges international expectations with local traditions. The community is accustomed to welcoming visitors and providing services that meet international standards while maintaining the warmth and hospitality that characterizes Maldivian culture."]}],"island_faqs":[{"question":"Why is Hulhumale the best choice for convenient access to the Maldives?","answer":"Hulhumale offers unmatched convenience as the only destination in the Maldives directly connected to Velana International Airport via the Sinamale Bridge. This eliminates the need for boat transfers, reduces travel time and costs, and provides immediate access to modern amenities upon arrival. The island combines international hotel standards with tropical beauty, making it perfect for both short stopovers and extended stays while serving as an ideal base for exploring the entire country."},{"question":"What modern amenities and facilities are available on Hulhumale?","answer":"Hulhumale offers comprehensive modern infrastructure including international hotels, shopping centers, restaurants serving diverse cuisines, healthcare facilities, banks and ATMs, fitness centers, recreational parks, and reliable telecommunications. The island features wide paved roads, public transportation, 24/7 services, and all urban conveniences while maintaining beautiful artificial beaches and tropical landscaping. This makes it the most developed and accessible destination in the Maldives."},{"question":"How do I get to Hulhumale from the airport?","answer":"Hulhumale is incredibly accessible from Velana International Airport, being only 7 kilometers away and connected by the Sinamale Bridge. This direct connectivity makes Hulhumale the most convenient destination in the Maldives, with no boat transfers required regardless of weather conditions."},{"question":"What types of accommodation are available on Hulhumale?","answer":"All accommodations benefit from the island''s modern infrastructure, reliable utilities, and urban amenities. The variety ensures options for every budget and preference while maintaining high standards and convenient access to facilities and transportation."}],"island_nearby_slugs":["himmafushi","huraa","dhiffushi","maafushi","gulhi","guraidhoo","male","kaashidhoo","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'hulhumale';


-- huraa
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, North Male Atoll"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 900 residents"},{"label":"Size","value":"0.9 km long, 0.4 km wide"},{"label":"Distance from Male","value":"17 km"},{"label":"Transfer Options","value":"Public ferry, speedboat"},{"label":"Known For","value":"Traditional fishing village, cultural heritage, authentic experiences"},{"label":"Best For","value":"Cultural enthusiasts, peaceful retreats, authentic experiences"}],"island_overview":["Located in the northern part of Kaafu Atoll approximately 17 kilometers from Male, Huraa Island stands as one of the most authentic and traditional fishing villages in the Maldives. This charming island offers visitors a genuine glimpse into traditional Maldivian life, where centuries-old customs and modern hospitality blend seamlessly to create an unforgettable cultural experience.","What makes Huraa truly special is its commitment to preserving traditional Maldivian culture while welcoming visitors with open arms. The island maintains its authentic character as a working fishing village, where traditional dhonis (boats) still set sail daily, and time-honored crafts and customs continue to thrive alongside a growing but respectful tourism industry.","Visitors to Huraa are drawn by its authentic cultural experiences, pristine natural beauty, peaceful atmosphere, and the opportunity to witness traditional Maldivian life firsthand. The island offers a perfect escape from commercialized tourism, providing intimate encounters with local culture and genuine hospitality in a stunning tropical setting."],"island_sections":[{"heading":"Location & Map","paragraphs":["Huraa Island is strategically positioned in the northern part of Kaafu Atoll (North Male Atoll), approximately 17 kilometers from Male. This convenient location provides easy accessibility while maintaining the peaceful, traditional atmosphere that makes the island so special for cultural immersion and authentic experiences.","The island''s position in the atoll offers protection from strong ocean currents while providing access to excellent fishing grounds that have sustained the community for generations. The surrounding waters feature clear lagoons and healthy coral reefs, perfect for snorkeling and observing marine life in their natural habitat."]},{"heading":"Huraa: Traditional Fishing Village & Cultural Heritage","paragraphs":["Huraa Island represents one of the most authentic examples of traditional Maldivian island life, where centuries-old customs, fishing traditions, and cultural practices continue to thrive in their original form. The island offers visitors rare insights into genuine Maldivian heritage and community life."]},{"heading":"Traditional Fishing Village","paragraphs":["Experience authentic Maldivian fishing culture with traditional dhonis, time-honored fishing techniques, and the daily rhythms of a working fishing community that has remained unchanged for generations."]},{"heading":"Rich Cultural Heritage","paragraphs":["Discover preserved traditional crafts, music, dance, and customs that showcase authentic Maldivian culture, with opportunities to learn from local artisans and cultural practitioners."]},{"heading":"Authentic Community Life","paragraphs":["Witness genuine island community life, participate in local activities, and experience the warm hospitality and strong social bonds that characterize traditional Maldivian society."]},{"heading":"Pristine Natural Environment","paragraphs":["Enjoy unspoiled beaches, clear lagoons, and healthy coral reefs in a peaceful setting that showcases the natural beauty of the Maldives without commercial development."]},{"heading":"Traditional Practices","paragraphs":["Huraa preserves authentic Maldivian traditions:"]},{"heading":"Cultural Experiences","paragraphs":["Authentic cultural activities available to visitors:"]},{"heading":"Activities & Experiences","paragraphs":["Huraa offers unique cultural and natural experiences that showcase authentic Maldivian life and traditions. The island''s activities focus on cultural immersion, traditional practices, and peaceful enjoyment of the natural environment in an unspoiled setting."]},{"heading":"Cultural Immersion","paragraphs":["Experience authentic Maldivian culture through traditional crafts, music, dance, and daily life activities with local families and artisans."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen on traditional dhonis to learn time-honored fishing techniques and experience the island''s primary livelihood firsthand."]},{"heading":"Peaceful Snorkeling","paragraphs":["Explore pristine coral reefs and marine life in uncrowded waters, perfect for peaceful underwater exploration and photography."]},{"heading":"Village Exploration","paragraphs":["Take guided walks through the traditional village to observe daily life, architecture, and community activities in an authentic setting."]},{"heading":"Traditional Crafts","paragraphs":["Learn traditional handicrafts including mat weaving, rope making, and dhoni model building from skilled local artisans."]},{"heading":"Peaceful Beach Time","paragraphs":["Enjoy pristine, uncrowded beaches perfect for relaxation, meditation, and connecting with the natural beauty of the Maldives."]},{"heading":"People & Community Life","paragraphs":["Huraa is home to a tight-knit community of approximately 900 residents who have successfully preserved their traditional way of life while graciously welcoming visitors to share in their cultural heritage. The island represents one of the most authentic examples of traditional Maldivian society, where community bonds, cultural practices, and sustainable living remain central to daily life."]},{"heading":"Traditional Community Structure","paragraphs":["The island maintains traditional community structures and social systems that have governed Maldivian society for centuries. Extended families play central roles in community life, with elders respected for their wisdom and younger generations learning traditional skills and values through direct participation in community activities and cultural practices."]},{"heading":"Cultural Preservation","paragraphs":["Huraa''s residents are passionate guardians of Maldivian cultural heritage, actively preserving traditional crafts, music, dance, and oral traditions. The community has made conscious efforts to maintain their cultural identity while selectively embracing beneficial aspects of modernity, creating a living museum of authentic Maldivian life."]},{"heading":"Sustainable Living","paragraphs":["The community practices traditional sustainable living methods, including traditional fishing techniques, local food production, and resource conservation practices that have sustained the island for generations. This approach to sustainability provides valuable lessons for visitors about living in harmony with the natural environment."]}],"island_faqs":[{"question":"What makes Huraa Island special for cultural experiences?","answer":"Huraa Island is one of the most authentic traditional fishing villages in the Maldives, where centuries-old customs and practices continue to thrive in their original form. The island offers genuine cultural immersion opportunities including traditional fishing expeditions, handicraft workshops, cultural performances, and intimate interactions with local families. Visitors can witness and participate in authentic Maldivian life that has remained largely unchanged for generations."},{"question":"What cultural activities can I experience on Huraa?","answer":"Huraa offers unique cultural activities including traditional fishing trips with local fishermen, handicraft workshops with skilled artisans, traditional cooking classes, cultural performances featuring music and dance, village walks with cultural interpretation, and traditional dhoni sailing experiences. Visitors can also participate in community festivals, learn traditional crafts like mat weaving and rope making, and experience authentic family hospitality through homestay programs."},{"question":"How do I get to Huraa Island?","answer":"Huraa Island is easily accessible from Male, being only 17 kilometers away. Some cultural tour operators also offer traditional dhoni boat experiences for a more authentic arrival experience."},{"question":"What should I expect from accommodation on Huraa?","answer":"Accommodation on Huraa focuses on authentic cultural experiences through family-run guesthouses and small cultural heritage hotels. Properties typically offer traditional Maldivian hospitality, home-cooked local meals, cultural activities, and personal interactions with local families."}],"island_nearby_slugs":["himmafushi","dhiffushi","maafushi","gulhi","guraidhoo","hulhumale","male","kaashidhoo","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'huraa';


-- ihavandhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Ihavandhoo Island?","answer":"Weekly ferries from Male take 16-18 hours."},{"question":"When is the best time to visit?","answer":"December-April offers dry, sunny weather with calm seas. Water remains warm year-round."},{"question":"What makes Ihavandhoo special?","answer":"Its authentic northern culture, fishing heritage, and pristine environment away from mass tourism."},{"question":"Are there dress requirements?","answer":"Modest dress in public (shoulders/knees covered). Swimwear only at designated bikini beach."},{"question":"What marine life will I see?","answer":"Reef sharks, turtles, rays, and abundant tropical fish on the healthy house reef."}],"island_nearby_slugs":[]}'::jsonb
where node_type = 'location' and slug = 'ihavandhoo';


-- inguraidhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 600 residents"},{"label":"Size","value":"0.6 km long, 0.3 km wide"},{"label":"Distance from Male","value":"180 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat"},{"label":"Known For","value":"Pristine beaches, excellent fishing, peaceful atmosphere"},{"label":"Best For","value":"Nature lovers, cultural travelers, budget travelers"}],"island_overview":["Nestled in the pristine waters of Raa Atoll, Inguraidhoo Island offers visitors a unique opportunity to experience traditional Maldivian culture while enjoying some of the most beautiful beaches in the northern Maldives.","Inguraidhoo stands out for its untouched natural beauty, crystal-clear lagoons, and vibrant marine life. The island maintains its traditional character while welcoming visitors with genuine Maldivian hospitality.","What makes Inguraidhoo truly special is its peaceful atmosphere, excellent marine life, and the opportunity to experience authentic island culture. Visitors can enjoy budget-friendly accommodations, delicious local cuisine, and unforgettable underwater adventures."],"island_sections":[{"heading":"Location & Map","paragraphs":["Inguraidhoo Island is located in the northern part of Raa Atoll, approximately 180 kilometers from Male. This location offers visitors a more remote and authentic experience compared to more tourist-heavy areas.","The island''s position provides natural protection from strong currents while maintaining access to excellent fishing grounds and snorkeling spots in the surrounding waters."]},{"heading":"Inguraidhoo: Natural Beauty & Marine Wonders","paragraphs":["Inguraidhoo Island is renowned for its exceptional natural beauty, featuring powder-white sand beaches, crystal-clear turquoise waters, and vibrant marine life. The island offers an unspoiled tropical paradise perfect for relaxation and exploration."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Inguraidhoo boasts beautiful beaches with soft white sand and crystal-clear waters perfect for swimming and sunbathing."]},{"heading":"Excellent Snorkeling","paragraphs":["The island''s house reef features diverse marine life, colorful corals, and good underwater visibility."]},{"heading":"Authentic Island Culture","paragraphs":["Experience genuine Maldivian hospitality and traditional island life in a peaceful setting."]},{"heading":"Pristine Sandbank Visits","paragraphs":["Explore nearby uninhabited sandbanks for the ultimate desert island experience."]},{"heading":"Beach Highlights","paragraphs":["Inguraidhoo''s coastal features include:"]},{"heading":"Marine Environment","paragraphs":["The island''s underwater world features:"]},{"heading":"Activities & Experiences","paragraphs":["Inguraidhoo offers a variety of activities focused on marine adventures, cultural experiences, and natural exploration."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the vibrant house reef featuring colorful corals and tropical fish."]},{"heading":"Scuba Diving Adventures","paragraphs":["Discover dive sites around Raa Atoll with professional operators."]},{"heading":"Island Hopping Tours","paragraphs":["Visit nearby islands and discover uninhabited sandbanks."]},{"heading":"Traditional Night Fishing","paragraphs":["Join local fishermen for authentic night fishing experiences."]},{"heading":"Cultural Experiences","paragraphs":["Immerse yourself in local community life and traditions."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll."]},{"heading":"People & Community Life","paragraphs":["Inguraidhoo is home to a close-knit community of approximately 600 residents who have preserved traditional Maldivian ways of life. The island''s population is renowned for their warmth and hospitality."]},{"heading":"Daily Life","paragraphs":["Life on Inguraidhoo follows the natural rhythms of island living, beginning with morning prayers and continuing with fishing, community work, and family activities."]},{"heading":"Culture & Traditions","paragraphs":["Inguraidhoo preserves authentic Maldivian cultural traditions including music, dance, and handicrafts. The community celebrates Islamic festivals with enthusiasm."]},{"heading":"Local Economy","paragraphs":["The island''s economy is primarily based on fishing and increasingly tourism. Many families engage in traditional occupations while also participating in the growing tourism sector."]}],"island_faqs":[{"question":"How do I get to Inguraidhoo Island?","answer":"Inguraidhoo Island can be reached by domestic flight to Ifuru Airport (55 minutes from Male) followed by a 30-minute speedboat ride. Seaplane transfers are also available but depend on weather conditions."},{"question":"What is the best time to visit Inguraidhoo?","answer":"The best time to visit is during the dry season from December to April when weather conditions are most favorable. However, the island can be visited year-round."},{"question":"What accommodation options are available?","answer":"Inguraidhoo offers various budget-friendly accommodations including family guesthouses and beachfront properties."},{"question":"What activities are available?","answer":"Inguraidhoo offers snorkeling, diving excursions, island hopping tours, cultural experiences, and fishing trips."}],"island_nearby_slugs":["rasgetheemu","ungoofaaru","rasmaadhoo","vaadhoo","alifushi","angolhitheemu","dhuvaafaru","fainu","hulhudhuffaaru","innamaadhoo","kinolhas","maakurathu","maduvvaree","meedhoo"]}'::jsonb
where node_type = 'location' and slug = 'inguraidhoo';


-- innamaadhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,600 residents"},{"label":"Size","value":"1.4 km long, 0.9 km wide"},{"label":"Distance from Male","value":"158 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Vibrant culture, stunning beaches, excellent snorkeling"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, snorkelers, adventure seekers"}],"island_overview":["Innamaadhoo Island is a vibrant local island in Raa Atoll that offers visitors an energetic glimpse into traditional Maldivian life. This lively island combines natural beauty with a dynamic atmosphere, providing an ideal destination for travelers seeking exciting cultural experiences and stunning tropical surroundings.","Known for its spectacular beaches, vibrant coral reefs, and excellent marine biodiversity, Innamaadhoo provides outstanding opportunities for snorkeling, swimming, and underwater exploration. The island''s energetic community embraces visitors with traditional Maldivian warmth and shares their lively way of life with dynamic hospitality.","What makes Innamaadhoo special is its vibrant natural environment and lively island setting. Visitors can enjoy stunning beaches, explore rich marine ecosystems, and experience dynamic island culture while staying in comfortable accommodations that showcase the vibrant Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Innamaadhoo Island is strategically located in the northern part of Raa Atoll, approximately 158 kilometers from Male. This location provides a vibrant and exciting experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to stunning coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Raa Atoll."]},{"heading":"Innamaadhoo: Vibrant Paradise & Marine Splendor","paragraphs":["Innamaadhoo Island is blessed with exceptional natural beauty, featuring stunning white sand beaches, crystal-clear turquoise waters, and one of the most vibrant marine environments in Raa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a lively, energetic setting."]},{"heading":"Stunning White Sand Beaches","paragraphs":["Innamaadhoo features vibrant white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and exciting beach activities."]},{"heading":"Vibrant House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers spectacular snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Vibrant Island Community","paragraphs":["Experience the energetic spirit of traditional island life with friendly locals and vibrant Maldivian culture in a lively community setting."]},{"heading":"Exciting Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and stunning islands around Innamaadhoo for vibrant tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Innamaadhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Innamaadhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Innamaadhoo offers a perfect blend of marine adventures, cultural experiences, and vibrant activities. The island''s energetic environment and lively atmosphere provide ideal conditions for various activities in an exciting, dynamic setting."]},{"heading":"Vibrant House Reef Snorkeling","paragraphs":["Explore the spectacular house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in vibrant waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby stunning dive sites with professional dive operators offering guided dives and certification courses in vibrant marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, stunning sandbanks, and discover the natural beauty of Raa Atoll with exciting exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in vibrant community settings."]},{"heading":"Dynamic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience vibrant Maldivian island life with exciting cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in vibrant waters."]},{"heading":"Community Life & Culture","paragraphs":["Innamaadhoo is home to approximately 1,600 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and vibrant cultural traditions that create a lively atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Innamaadhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains a vibrant atmosphere where visitors can experience dynamic Maldivian culture and customs in their most lively, energetic setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this vibrant island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Innamaadhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and vibrant cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Innamaadhoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Raa Atoll."},{"question":"What is the best time to visit Innamaadhoo?","answer":"The best time to visit Innamaadhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more vibrant local atmosphere."},{"question":"What accommodation options are available on Innamaadhoo?","answer":"Innamaadhoo offers various accommodations including vibrant guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a lively setting."},{"question":"What makes Innamaadhoo''s culture special?","answer":"Innamaadhoo is known for its vibrant and dynamic community atmosphere. The island maintains traditional Maldivian cultural practices while offering an energetic environment perfect for cultural exploration. Visitors can experience exciting cultural exchanges and participate in lively community activities."}],"island_nearby_slugs":["rasgetheemu","ungoofaaru","rasmaadhoo","vaadhoo","alifushi","angolhitheemu","dhuvaafaru","fainu","hulhudhuffaaru","inguraidhoo","kinolhas","maakurathu","maduvvaree","meedhoo"]}'::jsonb
where node_type = 'location' and slug = 'innamaadhoo';

